import {openHarness,_electron,project} from './redesign-harness.mjs';import {writeFile,mkdir} from 'node:fs/promises';import {join,resolve} from 'node:path';import assert from 'node:assert/strict';
const desktop=process.argv.includes('--desktop'),prefix=desktop?'desktop-':'';
const h=await openHarness(desktop?'data-gap-desktop-acceptance':'data-gap-acceptance'),out=resolve('output/data-gaps-2026-10-25'),checks=[],errors=[];await mkdir(out,{recursive:true});let app;
try{
 if(desktop)app=await _electron.launch({executablePath:join(project,'.runtime/desktop-data-gaps-20261025/小木-win32-x64/小木.exe'),env:{...h.env,WUJIAN_DESKTOP_PROFILE:join(h.root,'data-gap-desktop-profile')},cwd:project});
 const p=app?await app.firstWindow():await h.browser.newPage({viewport:{width:1440,height:900}});if(app)await p.waitForSelector('#mainNav');p.on('pageerror',e=>errors.push(e.message));await p.goto(h.base+'/market-panorama.html#variety');await p.waitForSelector('.detail-identity');
 await p.locator('#refreshMode').selectOption('supplement');await p.locator('#refreshButton').click();let status;
 for(let i=0;i<180;i++){status=await fetch(h.base+'/api/market-panorama/status').then(r=>r.json());if(status.job&&!['running','queued'].includes(status.job.status))break;await p.waitForTimeout(1000)}
 assert.ok(status.job&&!['running','queued','failed'].includes(status.job.status),JSON.stringify(status.job));await writeFile(join(out,prefix+'real-refresh-job.json'),JSON.stringify(status.job,null,2));checks.push({name:'点击原同步按钮，六所独立采集，失败不丢弃其他来源',status:status.job.status,results:status.job.results});
 await p.locator('[data-nav=variety]').click();await p.locator('[data-picker-sector="农产品"]').click();await p.locator('[data-pick=M]').click();await p.waitForSelector('[data-evidence=warehouse] details');await p.locator('[data-evidence=warehouse] summary').click();await p.locator('[data-evidence=warehouse]').scrollIntoViewIfNeeded();const warehouse=await p.locator('[data-evidence=warehouse]').innerText();assert.match(warehouse,/67 条历史/);assert.match(warehouse,/2026-07-15/);assert.match(warehouse,/2026-10-23/);await p.screenshot({path:join(out,prefix+'warehouse-history-click.png')});checks.push({name:'豆粕仓单真实历史展开',text:warehouse});
 await p.locator('[data-picker-sector="有色"]').click();await p.locator('[data-pick=CU]').click();await p.waitForFunction(()=>document.querySelector('[data-evidence=roll]')?.textContent.includes('ln('),null,{timeout:30000});const cu=await fetch(h.base+'/api/market-panorama/variety?product=CU&date=2026-10-25').then(r=>r.json());assert.ok(cu.rollYield);assert.ok(Math.abs(cu.rollYield.rate-Math.log(cu.rollYield.near.close/cu.rollYield.far.close)*12/cu.rollYield.monthGap)<1e-10);await p.locator('[data-evidence=roll]').scrollIntoViewIfNeeded();await p.screenshot({path:join(out,prefix+'roll-reference-click.png')});checks.push({name:'沪铜展期实际合约与独立复算一致',value:cu.rollYield});
 await p.locator('[data-picker-sector="农产品"]').click();await p.locator('[data-pick=M]').click();await p.waitForFunction(()=>document.querySelector('[data-evidence=roll]')?.textContent.includes('412'),null,{timeout:30000});checks.push({name:'大商所展期缺口如实显示HTTP412'});
 await p.locator('#sourcesButton').click();const sources=await p.locator('#sourceBody').innerText();assert.match(sources,/部分取得/);assert.match(sources,/HTTP接口返回412/);await p.screenshot({path:join(out,prefix+'source-gaps-click.png')});checks.push({name:'来源弹窗同时显示已取得与缺口',text:sources});
 assert.deepEqual(errors,[]);await writeFile(join(out,prefix+'click-result.json'),JSON.stringify({checks,errors,desktop,productionWritten:false},null,2));console.log(JSON.stringify({checks:checks.map(c=>({...c,text:c.text?.slice(0,220)})),errors,desktop,productionWritten:false}));
}finally{if(app)await app.close();await h.close()}
